<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agency subscription | CareSys</title><link rel="stylesheet" href="/assets/caresys.css?v=<?= (int)filemtime(FCPATH.'assets/caresys.css') ?>"></head><body><a class="skip" href="#main-content">Skip to content</a><div class="shell"><?= view('components/workspace_sidebar',['w'=>$w,'memberships'=>$memberships,'base'=>$base,'page'=>'billing']) ?><div class="main"><main id="main-content" class="content"><section class="card billing-overview"><div class="standalone-notification-bar"><?= view('components/notification_menu',['w'=>$w]) ?></div><h1><?= $status['owner']?'Subscription & free trial':'Agency account' ?></h1><p><?= esc($agency['name']) ?></p>
<?php if(session('message')): ?><p class="alert" role="status"><?= esc(session('message')) ?></p><?php endif ?><?php if(session('error')): ?><p class="alert error" role="alert"><?= esc(session('error')) ?></p><?php endif ?>
<?php if(!$status['owner']): ?><p role="alert"><?= esc($status['notice']) ?></p><?php else: ?>
<?php $cardReady=(bool)($status['card_verified']??false);$pendingCheckout=$checkout??null;$step=$cardReady?(!$status['locked']?3:2):1; ?>
<ol class="billing-steps" aria-label="Agency setup progress"><?php foreach([1=>'Save a card',2=>'Choose modules',3=>'Open workspace'] as $number=>$label): ?><li <?= $number===$step?'aria-current="step"':'' ?>><span><?= $number ?></span><?= esc($label) ?></li><?php endforeach ?></ol>
<div class="billing-terms"><strong>No automatic subscription charge</strong><p>No subscription payment is taken during your free trial. After it ends, an owner must approve payment to restore agency access.</p></div>
<?php if($status['trial_ends_at']??null): ?><p class="billing-date">Free trial ends <strong><?= esc($status['trial_ends_at']) ?> UTC</strong></p><?php endif ?>
<?php if($status['paid_until']??null): ?><p class="billing-date">Paid access ends <strong><?= esc($status['paid_until']) ?> UTC</strong></p><?php endif ?>
<?php if($pendingCheckout): ?><section class="billing-next" aria-labelledby="billing-next-title"><span class="badge">Action needed</span><h2 id="billing-next-title"><?= $pendingCheckout['purpose']==='setup'?'Confirm your saved card':'Confirm your payment' ?></h2><p>You have returned from Stripe. Confirm the result to continue.</p><p class="sub">You do not need to enter your card again. CareSys checks the result directly with Stripe.</p><form method="post" action="<?= esc($base) ?>/billing/actions/complete"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="ref" value="<?= esc($pendingCheckout['ref'],'attr') ?>"><button type="submit"><?= $pendingCheckout['purpose']==='setup'?'Confirm saved card':'Confirm payment result' ?></button></form></section>
<?php else: ?>
<?php if(!$status['locked']): ?><section class="billing-next"><span class="badge"><?= $status['state']==='trial'?'Free trial active':'Subscription active' ?></span><h2>Your agency workspace is ready</h2><p>Your selected modules are available. Open your workspace to get started.</p><a class="billing-open" href="<?= esc($base) ?>/dashboard">Open agency workspace &rarr;</a></section><?php endif ?>
<?php if($status['local_simulator']??false): ?><aside class="notice" role="status"><strong>Local billing test mode</strong><p>No real card is required and no money is collected. Use these controls to test module selection, invoices, trial expiry and owner payment approval. Test access works only while this local simulator is enabled.</p>
<?php $testActions=[];if(!($status['card_verified']??false))$testActions['test-setup']='Simulate card setup';if($status['state']==='trial' && ($status['simulated_billing']??false))$testActions['test-expire']='End test trial now';if($status['state']==='payment_required' && ($status['simulated_billing']??false) && ($status['invoice_ref']??null))$testActions['test-payment']='Approve simulated invoice payment';foreach($testActions as $testAction=>$label): ?>
<form method="post" action="<?= esc($base) ?>/billing/actions/<?= esc($testAction) ?>"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="invoice_ref" value="<?= esc($status['invoice_ref']??'','attr') ?>"><label><input type="checkbox" name="confirm" value="yes" required> I confirm this local test action only.</label><p><button><?= esc($label) ?></button></p></form>
<?php endforeach ?></aside><?php elseif($status['simulated_billing']??false): ?><p class="notice">This account used simulated billing. Re-enable the local simulator to continue testing. Use a fresh agency for real Stripe billing.</p><?php endif ?>
<?php if(!($status['stripe_configured']??false) && !($status['local_simulator']??false)): ?><p class="notice">Secure card setup is awaiting Stripe configuration by the platform administrator. Trial activation and payment remain unavailable until configured.</p><?php endif ?>
<?php if(!($status['card_verified']??false)): ?><?php if(!($status['local_simulator']??false)): ?><h2 class="billing-step-heading">Step 1 &middot; Save your card securely</h2><p>Stripe handles your card details securely. Your <?= (int)$status['trial_days'] ?>-day trial starts after card verification and module selection. Your bank may show a temporary verification authorization.</p><form method="post" action="<?= esc($base) ?>/billing/actions/setup"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><label><input type="checkbox" name="confirm" value="yes" required> I agree to save a card with Stripe and understand that later payment requires my approval.</label><p><button <?= !($status['stripe_configured']??false)?'disabled':'' ?>>Continue to secure card setup</button></p></form>
<?php endif ?><?php else: ?><p>Verified card: <?= esc($status['card_brand']??'Card') ?> ending <?= esc($status['card_last4']??'') ?></p><?php if(!$status['locked']): ?><details class="billing-edit"><summary>Change package, modules or worker count</summary><?php else: ?><h2 class="billing-step-heading">Step 2 &middot; Choose your package and modules</h2><p>Select a package, check worker coverage and request your invoice to start the trial.</p><?php endif ?><?php echo view('components/subscription_quote',compact('agency','base','nonce','active_worker_count')+['subscription_invoices'=>[],'billing_action'=>$base.'/billing/actions/quote']); ?><?php if(!$status['locked']): ?></details><?php endif ?>
<?php if($status['state']==='payment_required' && !($status['simulated_billing']??false)): ?><h2>Trial or paid access has ended — approve payment to continue</h2><p>No automatic charge has been made. Review your current invoice and approve the amount on Stripe. Successful payment unlocks this agency for 30 days; renewal also requires approval.</p><?php $current=null;foreach($subscription_invoices as $item)if($item['ref']===($status['invoice_ref']??''))$current=$item; ?><?php if($current && $current['state']==='issued'): ?><p><?= esc($current['invoice_no']) ?> — USD <?= number_format($current['total_cents']/100,2) ?> before any applicable tax shown by Stripe</p><form method="post" action="<?= esc($base) ?>/billing/actions/payment"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="invoice_ref" value="<?= esc($current['ref']) ?>"><label><input type="checkbox" name="confirm" value="yes" required> I approve proceeding to payment for this invoice. Stripe will show the final amount before I pay.</label><p><button <?= !($status['stripe_configured']??false)?'disabled':'' ?>>Approve payment on Stripe</button></p></form><?php else: ?><p>Choose your modules above to request a current invoice for the next 30 days.</p><?php endif;endif;endif ?>
<?php endif ?>
<?php if($subscription_invoices && !$pendingCheckout): ?><section class="billing-invoice-section"><h2>Your invoices</h2><p class="sub">Download a proposal or subscription summary.</p><?php foreach($subscription_invoices as $invoice): ?><div class="billing-invoice-row"><div><strong><?= esc($invoice['invoice_no']) ?></strong><p class="sub">USD <?= number_format($invoice['total_cents']/100,2) ?> &middot; <?= $invoice['state']==='paid'?'Paid':'Pro forma' ?></p></div><a href="<?= esc($base.'/subscription-invoices/'.$invoice['ref'].'/download','attr') ?>">Download PDF</a></div><?php endforeach ?></section><?php endif;endif ?></section></main></div></div><script src="/assets/caresys.js" defer></script></body></html>
